// ---------------------------------------------------------------- fireworks over the arena
function fireworksShow(world) {
  const PAL = [['#ff3a4a', '#ffffff'], ['#ffffff', '#c8102e', '#ffd23a'], ['#ffd23a', '#ff8a3a'], ['#c8102e', '#ff7ae0'], ['#7ae0ff', '#ffffff']];
  const show = {
    kind: 'laststand_fireworks', x: 0, y: 0, removed: false, next: 2, finale: 0, rockets: [], flashes: [],
    launch(w) {
      const p = w.player;
      const bx = Math.min(p.x, 30), by = Math.min(p.y, 40);
      this.rockets.push({ x: bx - 3 - Math.random() * 9, y: by - 3 - Math.random() * 9, z: 4, vz: 10 + Math.random() * 3, t: 0, fuse: 0.75 + Math.random() * 0.4, pal: PAL[Math.floor(Math.random() * PAL.length)] });
      if (Math.random() < 0.5) w.sfx('whooshLight', { x: p.x - 6, y: p.y - 6 });
    },
    update(w, dt) {
      this.next -= dt;
      if (this.finale > 0) this.finale -= dt;
      if (this.next <= 0) { this.next = this.finale > 0 ? 0.18 + Math.random() * 0.3 : 2.2 + Math.random() * 3.8; this.launch(w); }
      for (const r of this.rockets) {
        r.t += dt; r.z += r.vz * dt; r.vz -= 4 * dt;
        if (w.fx && Math.random() < 0.6) w.fx.add({ x: r.x, y: r.y, z: r.z - 0.2, life: 0.35, color: '#ffd8a0', g: 0.05 });
        if (r.t >= r.fuse) {
          r.done = true;
          const n = 26 + Math.floor(Math.random() * 14);
          for (let i = 0; i < n && w.fx; i++) {
            const a = Math.random() * Math.PI * 2, e = Math.random() * Math.PI - Math.PI / 2, s = 2.2 + Math.random() * 1.6;
            w.fx.add({ x: r.x, y: r.y, z: r.z, vx: Math.cos(a) * Math.cos(e) * s, vy: Math.sin(a) * Math.cos(e) * s, vz: Math.sin(e) * s * 1.4, life: 0.9 + Math.random() * 0.6, color: r.pal[i % r.pal.length], size: Math.random() < 0.3 ? 2 : 1, g: 0.06 });
          }
          if (w.fx) w.fx.add({ x: r.x, y: r.y, z: r.z, kind: 'flash', life: 0.15, size: 10, color: '#ffffff', g: 0 });
          this.flashes.push({ x: r.x - r.z * 1.25, y: r.y - r.z * 1.25, t: 0, color: r.pal[0] });
          w.sfx(Math.random() < 0.5 ? 'boom' : 'explosion', { x: r.x, y: r.y });
        }
      }
      this.rockets = this.rockets.filter(r => !r.done);
      for (const f of this.flashes) f.t += dt;
      this.flashes = this.flashes.filter(f => f.t < 0.6);
    },
    draw(ctx, w) {
      for (const r of this.rockets) {
        const s = toScreen(r.x, r.y, r.z);
        ctx.fillStyle = '#ffffff'; ctx.fillRect(Math.round(s.x), Math.round(s.y), 1, 2);
        ctx.fillStyle = '#ffb060'; ctx.fillRect(Math.round(s.x), Math.round(s.y) + 2, 1, 4);
      }
      const L = (w.lightsDynamic ||= []);
      for (const f of this.flashes) L.push({ x: f.x, y: f.y, z: 0, r: 7, color: f.color, intensity: 0.55 * (1 - f.t / 0.6) });
      if (w._lsFlash && w.time - w._lsFlash.t < 0.4) L.push({ x: w._lsFlash.x, y: w._lsFlash.y, z: 0.5, r: 5, color: '#ffd080', intensity: 0.9 * (1 - (w.time - w._lsFlash.t) / 0.4) });
    },
    depth() { return 1e9; },
  };
  world.addActor(show);
  return show;
}

// ---------------------------------------------------------------- "THE REUNION": enemies from earlier levels
const BASE_ROSTER = new Set(['rival', 'awayfan', 'bruiser', 'bottler', 'steward', 'ganger', 'firm']);
function reunionWave() {
  const others = Object.entries(ENEMIES)
    .filter(([id, d]) => !d.boss && !BASE_ROSTER.has(id) && !id.startsWith('laststand_') && !d.think)
    .map(([id]) => id);
  for (let i = others.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [others[i], others[j]] = [others[j], others[i]]; }
  const fill = ['steward', 'ganger', 'bottler', 'ganger'];
  const spots = [
    { x: 14.5, y: 32.5, from: { x: 45, y: 36 } }, { x: 24.5, y: 40.5, from: { x: 45, y: 36.5 } },
    { x: 28.5, y: 30.5, from: { x: 27, y: 20 } }, { x: 8.5, y: 43.5, from: { x: 3.5, y: 50 } },
  ];
  return { msg: 'THE REUNION!', enemies: spots.map((s, i) => ({ type: others[i] || fill[i], ...s })) };
}

